// components/my-portfolios/EditSquareProfileSidebar.tsx
"use client"

import { useEffect, useRef, useState } from "react"
import ArrowLeft from "@/components/icons/ArrowLeft"
import ImageIcon from "@/components/icons/ImageIcon"
import SecondaryButton from "@/components/buttons/SecondaryButton"
import Tag from "@/components/onboarding/Tag"

type Props = {
  backHref: string

  // colors (optional)
  bannerColor?: string
  backgroundColor?: string
  onChangeBannerColor?: (hex: string) => void
  onChangeBackgroundColor?: (hex: string) => void

  // profile image
  profileImageUrl?: string
  onChangeProfileImage?: (file: File, objectUrl: string) => void

  // text fields
  businessName?: string
  displayName?: string
  onChangeBusinessName?: (val: string) => void
  onChangeDisplayName?: (val: string) => void

  // links row (for now we show the "add link" icon area like Figma)
  // you can expand later into real editable social links
  showAddLink?: boolean
  onAddLinkClick?: () => void

  // tags
  merchTags?: string[]

  // previous vends (simple list)
  previousVends?: string[]

  // location/email
  locationText?: string
  email?: string

  // bottom actions
  publishLabel?: string
  onPublish?: () => void
  onOpenPreview?: () => void
}

export default function EditSquareProfileSidebar({
  backHref,

  bannerColor = "#FFFFFF",
  backgroundColor = "#F7F7F7",
  onChangeBannerColor,
  onChangeBackgroundColor,

  profileImageUrl,
  onChangeProfileImage,

  businessName = "Business Name",
  displayName = "Your Name",
  onChangeBusinessName,
  onChangeDisplayName,

  showAddLink = true,
  onAddLinkClick,

  merchTags = ["Prints", "Stickers"],
  previousVends = ["Vended Event 2025"],

  locationText = "City, State",
  email = "myemailaddress@konfolio.com",

  publishLabel = "Publish",
  onPublish,
  onOpenPreview,
}: Props) {
  const [localBanner, setLocalBanner] = useState(bannerColor)
  const [localBg, setLocalBg] = useState(backgroundColor)

  useEffect(() => setLocalBanner(bannerColor), [bannerColor])
  useEffect(() => setLocalBg(backgroundColor), [backgroundColor])

  // profile image upload
  const inputRef = useRef<HTMLInputElement | null>(null)
  const [localImgUrl, setLocalImgUrl] = useState(profileImageUrl || "")
  const objectUrls = useRef<string[]>([])

  useEffect(() => setLocalImgUrl(profileImageUrl || ""), [profileImageUrl])

  useEffect(() => {
    return () => {
      objectUrls.current.forEach((u) => URL.revokeObjectURL(u))
      objectUrls.current = []
    }
  }, [])

  const openPicker = () => inputRef.current?.click()

  const handleFile = (file: File) => {
    if (!file.type.startsWith("image/")) return
    const url = URL.createObjectURL(file)
    objectUrls.current.push(url)
    setLocalImgUrl(url)
    onChangeProfileImage?.(file, url)
  }

  const onInputChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0]
    if (!file) return
    handleFile(file)
    e.target.value = ""
  }

  const onDrop = (e: React.DragEvent) => {
    e.preventDefault()
    e.stopPropagation()
    const file = e.dataTransfer.files?.[0]
    if (!file) return
    handleFile(file)
  }

  const onDragOver = (e: React.DragEvent) => {
    e.preventDefault()
    e.stopPropagation()
  }

  return (
    <aside className="w-[316px] h-[982px] bg-white px-[20px] py-[40px] flex flex-col items-center gap-[10px]">
      {/* Frame 64 (top row) */}
      <div className="relative w-[276px] h-[36px] flex items-center justify-center gap-[40px]">
        {/* Back arrow (absolute like Figma) */}
        <div className="absolute left-0 top-1/2 -translate-y-1/2">
          <ArrowLeft href={backHref} className="w-[30px] h-[30px]" />
        </div>

        {/* Color Field */}
        <div className="flex items-center justify-end gap-[5px] w-[98px] h-[36px]">
          {/* Brush placeholder (optional): if you have a BrushIcon, swap it in */}
          <div className="w-[16px] h-[16px] relative opacity-80">
            <div className="absolute inset-0 rounded-[3px] border border-[#A5A5A5]" />
          </div>

          {/* Banner color swatch */}
          <label className="w-[36px] h-[36px] border border-[rgba(165,165,165,0.5)] bg-white cursor-pointer relative overflow-hidden">
            <span
              className="absolute inset-0"
              style={{ backgroundColor: localBanner }}
            />
            <input
              type="color"
              className="absolute inset-0 opacity-0 cursor-pointer"
              value={localBanner}
              onChange={(e) => {
                setLocalBanner(e.target.value)
                onChangeBannerColor?.(e.target.value)
              }}
              aria-label="Banner color"
            />
          </label>

          {/* Background color swatch */}
          <label className="w-[36px] h-[36px] border border-[rgba(165,165,165,0.5)] cursor-pointer relative overflow-hidden">
            <span
              className="absolute inset-0"
              style={{ backgroundColor: localBg }}
            />
            <input
              type="color"
              className="absolute inset-0 opacity-0 cursor-pointer"
              value={localBg}
              onChange={(e) => {
                setLocalBg(e.target.value)
                onChangeBackgroundColor?.(e.target.value)
              }}
              aria-label="Background color"
            />
          </label>
        </div>
      </div>

      {/* Profile block */}
      <div className="w-[276px] flex flex-col items-center gap-[30px]">
        {/* Profile picture (drag/drop + click) */}
        <div
          className="relative w-[189px] h-[189px] bg-white border border-[rgba(165,165,165,1)] border-[0.5px] rounded-[15px] overflow-hidden"
          onDrop={onDrop}
          onDragOver={onDragOver}
        >
          <input
            ref={inputRef}
            type="file"
            accept="image/*"
            className="hidden"
            onChange={onInputChange}
          />

          {/* Click target */}
          <button
            type="button"
            className="absolute inset-0"
            aria-label="Upload profile image"
            onClick={openPicker}
          >
            <span className="sr-only">Upload</span>
          </button>

          {/* Image preview */}
          {localImgUrl ? (
            // eslint-disable-next-line @next/next/no-img-element
            <img
              src={localImgUrl}
              alt=""
              className="absolute inset-0 w-full h-full object-cover pointer-events-none"
              draggable={false}
            />
          ) : null}

          {/* Placeholder content */}
          {!localImgUrl && (
            <div className="pointer-events-none absolute inset-0 flex flex-col items-center justify-center gap-[5px]">
              <div className="w-[52px] h-[52px] flex items-center justify-center text-[#A5A5A5] [&_path]:stroke-[#A5A5A5] [&_path]:fill-[#A5A5A5]">
                <ImageIcon />
              </div>
              <p className="m-0 w-[100px] font-inter font-normal text-[11px] leading-[13px] text-center text-[#A5A5A5]">
                Drop image here or click to open files
              </p>
            </div>
          )}
        </div>

        {/* Names */}
        <div className="w-[276px] flex flex-col items-center gap-[12px]">
          <input
            value={businessName}
            onChange={(e) => onChangeBusinessName?.(e.target.value)}
            placeholder="Business Name"
            className="
              w-full
              text-center
              font-inter font-normal
              text-[22px] leading-[140%]
              text-[#A5A5A5]
              placeholder:text-[#A5A5A5]
              bg-transparent
              outline-none
            "
          />

          <input
            value={displayName}
            onChange={(e) => onChangeDisplayName?.(e.target.value)}
            placeholder="Your Name"
            className="
              w-full
              text-center
              font-inter font-normal
              text-[15px] leading-[140%]
              text-[rgba(165,165,165,0.5)]
              placeholder:text-[rgba(165,165,165,0.5)]
              bg-transparent
              outline-none
            "
          />
        </div>

        {/* Social medias row (Add link placeholder) */}
        <div className="w-[276px] h-[24px] flex items-center justify-center gap-[10px]">
          {showAddLink ? (
            <button
              type="button"
              onClick={onAddLinkClick}
              className="w-[160px] h-[24px] flex items-center justify-center gap-[10px]"
              aria-label="Add link"
            >
              <div className="w-[24px] h-[24px] rounded-[6px] flex items-center justify-center">
                {/* If you have LinkIcon component, swap this in */}
                <div className="w-[24px] h-[24px] border border-[#A5A5A5] rounded-[6px]" />
              </div>
            </button>
          ) : null}
        </div>

        {/* Merch tags */}
        <div className="w-[276px] flex flex-wrap justify-center gap-[10px]">
          {merchTags.map((t, i) => (
            <Tag key={`${t}-${i}`} label={t} />
          ))}
        </div>

        {/* Previous vends */}
        <div className="w-[276px] flex flex-col items-center gap-[12px]">
          <p className="m-0 w-full text-center font-inter font-normal text-[15px] leading-[140%] text-[#A5A5A5]">
            Previous Vends
          </p>

          {previousVends.slice(0, 4).map((v, i) => (
            <p
              key={`${v}-${i}`}
              className="m-0 w-full text-center font-inter font-normal text-[15px] leading-[140%] text-[#D3D3D3]"
            >
              {v}
            </p>
          ))}
        </div>

        {/* Location + email */}
        <div className="w-[276px] flex flex-col items-center gap-[12px]">
          <div className="flex items-center justify-center gap-[5px] h-[12px]">
            {/* If you have a location icon, swap it in */}
            <div className="w-[12px] h-[12px] bg-[#A5A5A5] rounded-[3px]" />
            <p className="m-0 font-inter font-normal text-[15px] leading-[140%] text-[#A5A5A5]">
              {locationText}
            </p>
          </div>

          <p className="m-0 font-inter font-normal text-[15px] leading-[140%] text-[#A5A5A5]">
            {email}
          </p>
        </div>
      </div>

      {/* Viewing field (bottom row) */}
      <div className="w-[276px] h-[30px] flex items-center justify-center gap-[10px] mt-auto">
        <SecondaryButton onClick={onPublish}>{publishLabel}</SecondaryButton>

        <button
          type="button"
          aria-label="Open preview"
          onClick={onOpenPreview}
          className="
            w-[30px] h-[30px]
            bg-white
            border border-[#262626]
            rounded-full
            flex items-center justify-center
          "
        >
          {/* open_tab placeholder (swap to your icon if you have one) */}
          <span className="block w-[16px] h-[16px] border border-[#262626]" />
        </button>
      </div>
    </aside>
  )
}
